namespace ghidra.features.bsim.gui.search.results;






using docking.widgets.table;
using generic.theme;
using ghidra.docking.settings;
using ghidra.util.table.column;
using resources;

/**
 * Renderer for display BSim apply results from attempting to apply function names and signatures
 * from BSim Search results.
 */
public class BSimStatusRenderer : AbstractGColumnRenderer<BSimResultStatus> {
	private static readonly Icon NOT_APPLIED_ICON = null;
	private static readonly Icon NAME_APPLIED_ICON =
		new GIcon("icon.bsim.results.status.name.applied");
	private static readonly Icon SIGNATURE_APPLIED_ICON =
		new GIcon("icon.bsim.results.status.signature.applied");
	private static readonly Icon ERROR_ICON = Icons.ERROR_ICON;
	private static readonly Icon MATCHES_ICON = new GIcon("icon.bsim.results.status.matches");
	private static readonly Icon APPLIED_NO_LONGER_MATCHES_ICON = Icons.WARNING_ICON;
	private static readonly Icon NO_FUNCTION_ICON = Icons.STRONG_WARNING_ICON;
	private static readonly Icon IGNORED_ICON = new GIcon("icon.bsim.results.status.ignored");

	/* @Override */
	public Component getTableCellRendererComponent(GTableCellRenderingData data) {

		JLabel label = (JLabel) base.getTableCellRendererComponent(data);
		BSimResultStatus status = (BSimResultStatus) data.getValue();
		label.setText("");
		label.setIcon(getIcon(status));
		label.setToolTipText(status.getDescription());
		return label;
	}

	private Icon getIcon(BSimResultStatus status) {
		switch (status) {
			case NAME_APPLIED:
				return NAME_APPLIED_ICON;
			case SIGNATURE_APPLIED:
				return SIGNATURE_APPLIED_ICON;
			case ERROR:
				return ERROR_ICON;
			case MATCHES:
				return MATCHES_ICON;
			case NOT_APPLIED:
				return NOT_APPLIED_ICON;
			case APPLIED_NO_LONGER_MATCHES:
				return APPLIED_NO_LONGER_MATCHES_ICON;
			case NO_FUNCTION:
				return NO_FUNCTION_ICON;
			case IGNORED:
				return IGNORED_ICON;
			default:
				return ERROR_ICON;
		}
	}

	/* @Override */
	public string getFilterString(BSimResultStatus t, Settings settings) {
		return t.toString();
	}

}
